def largest_island(grid):
    n = len(grid); comp = [[0] * n for _ in range(n)]; size = {0: 0}; cid = 1
    for r in range(n):
        for c in range(n):
            if grid[r][c] and not comp[r][c]:
                st = [(r, c)]; comp[r][c] = cid; s = 0
                while st:
                    y, x = st.pop(); s += 1
                    for yy, xx in ((y + 1, x), (y - 1, x), (y, x + 1), (y, x - 1)):
                        if 0 <= yy < n and 0 <= xx < n and grid[yy][xx] and not comp[yy][xx]:
                            comp[yy][xx] = cid; st.append((yy, xx))
                size[cid] = s; cid += 1
    best = max(size.values())
    for r in range(n):
        for c in range(n):
            if not grid[r][c]:
                seen = {comp[yy][xx] for yy, xx in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)) if 0 <= yy < n and 0 <= xx < n}
                best = max(best, 1 + sum(size[i] for i in seen))
    return best

