int largestIsland(vector<vector<int>>& g) {
    int n = g.size(), id = 2; vector<int> sz(2, 0); int d[5] = {1, 0, -1, 0, 1};
    for (int r = 0; r < n; r++) for (int c = 0; c < n; c++) if (g[r][c] == 1) { int s = 0; vector<pair<int,int>> st{{r, c}}; g[r][c] = id;
        while (!st.empty()) { auto [y, x] = st.back(); st.pop_back(); s++; for (int k = 0; k < 4; k++) { int yy = y + d[k], xx = x + d[k+1]; if (yy >= 0 && yy < n && xx >= 0 && xx < n && g[yy][xx] == 1) { g[yy][xx] = id; st.push_back({yy, xx}); } } }
        sz.push_back(s); id++; }
    int best = *max_element(sz.begin(), sz.end());
    for (int r = 0; r < n; r++) for (int c = 0; c < n; c++) if (!g[r][c]) { int ids[4], m = 0, tot = 1; for (int k = 0; k < 4; k++) { int yy = r + d[k], xx = c + d[k+1]; if (yy < 0 || yy >= n || xx < 0 || xx >= n || !g[yy][xx]) continue; int v = g[yy][xx]; bool dup = false; for (int j = 0; j < m; j++) dup |= ids[j] == v; if (!dup) { ids[m++] = v; tot += sz[v]; } } best = max(best, tot); }
    return best;
}
